#!/usr/bin/env bash
# Generated by deploy/ubuntu/build_installer.py. Do not edit this bundle directly.
# Public installer: no backend source, issuer keys or credentials are bundled.
# Define the whole installer before invoking it so a truncated download cannot
# execute a partially received payload.
dali_toolkit_install() (
    set -Eeuo pipefail
    umask 077
    bundle=$(mktemp -d)
    trap 'rm -rf -- "$bundle"' EXIT
    cat > "$bundle/install_body.sh" <<'DALI_INSTALL_PAYLOAD_0_END'
#!/usr/bin/env bash
# Ubuntu host installer. HAProxy, certificates, DNS and firewall are node-owned.
set -Eeuo pipefail
umask 077

usage() {
    cat <<'HELP'
Usage: sudo bash install.sh [options]
  --binary PATH       Optional trusted local executable; otherwise reuse or download
  --channel CHANNEL   auto (prefer stable, otherwise dev), stable, or dev
  --use-mirror        Try TonyCloud mirror first, then GitHub
  --license PATH      Signed machine licence JSON; existing licence is kept otherwise
  --public-url URL    First-install default: https://dali.tonycloud.cn:28443
                      On reruns, preserve the existing URL unless explicitly supplied
  --node-key KEY      First-install default: this host's short hostname
  --pg-socket DIR     PostgreSQL socket directory (default: /var/run/postgresql)
  --pg-port PORT      PostgreSQL cluster port (default: 5432)
  --skip-packages     Use installed dependencies without running apt
  --help              Show this help

The standalone installer includes every template and downloads a signed binary.
With no licence, setup finishes but the service stays stopped; exit status 2
means a licence is required. Issue one for the printed machine hash and rerun
with --license. Existing runtime keys and updater settings are preserved.
Use the server's signed updater for binary upgrades after the first install.
HELP
}
fail() { printf 'ERROR: %s\n' "$*" >&2; exit 1; }
binary=
channel=auto
use_mirror=false
license_source=
public_url=
node_key=
pg_socket=/var/run/postgresql
pg_port=5432
skip_packages=false
while (($#)); do
    case "$1" in
        --help|-h) usage; exit 0 ;;
        --skip-packages) skip_packages=true; shift ;;
        --use-mirror) use_mirror=true; shift ;;
        --binary|--channel|--license|--public-url|--node-key|--pg-socket|--pg-port)
            (($# >= 2)) && [[ -n "$2" ]] || fail "Missing value for $1"
            case "$1" in
                --binary) binary=$2 ;;
                --channel) channel=$2 ;;
                --license) license_source=$2 ;;
                --public-url) public_url=$2 ;;
                --node-key) node_key=$2 ;;
                --pg-socket) pg_socket=$2 ;;
                --pg-port) pg_port=$2 ;;
            esac
            shift 2 ;;
        *) fail "Unknown option: $1" ;;
    esac
done
case "$channel" in auto|stable|dev) ;; *) fail 'Channel must be auto, stable or dev.' ;; esac
[[ $EUID == 0 ]] || fail 'Run this installer with sudo.'
[[ $(uname -s) == Linux && -d /run/systemd/system ]] || fail 'Ubuntu with a running systemd is required.'
# shellcheck source=/dev/null
source /etc/os-release
[[ ${ID:-} == ubuntu ]] || fail 'This installer supports Ubuntu.'
[[ ${VERSION_ID:-} =~ ^([0-9]+)\. ]] || fail 'Cannot determine the Ubuntu version.'
((BASH_REMATCH[1] >= 22)) || fail 'Ubuntu 22.04 or later is required.'
case "$(uname -m)" in
    x86_64) arch=x64 ;;
    aarch64) arch=aarch64 ;;
    *) fail 'Only Linux x64 and aarch64 are supported.' ;;
esac
script_dir=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)
for file in install_dependencies.sh install_config.py install_download.py server.env.example server-update.json dali-toolkit-server.service; do
    [[ -f "$script_dir/$file" ]] || fail "Incomplete installer payload: $file"
done
if [[ -n "$binary" ]]; then
    [[ -f "$binary" ]] || fail 'The --binary file does not exist.'
    binary=$(realpath -- "$binary")
elif [[ -f /usr/local/bin/dali-toolkit-server ]]; then
    binary=$(realpath -- /usr/local/bin/dali-toolkit-server)
fi
if [[ -n "$license_source" ]]; then
    [[ -f "$license_source" ]] || fail 'Licence file does not exist.'
    license_source=$(realpath -- "$license_source")
fi
exec 9>/run/lock/dali-toolkit-install.lock
flock -n 9 || fail 'Another DALI-Toolkit installer is running.'
# shellcheck source=/dev/null
source "$script_dir/install_dependencies.sh"
dali_install_dependencies "$skip_packages" "$pg_socket" "$pg_port"
for command in psql createuser createdb curl python3 openssl runuser systemctl systemd-analyze; do
    command -v "$command" >/dev/null || fail "Required command missing: $command"
done
python3 "$script_dir/install_config.py" check --public-url "$public_url" \
    --node-key "$node_key" --socket "$pg_socket" --port "$pg_port"
if systemctl is-active --quiet dalitoolkit.service; then
    fail 'The legacy dalitoolkit.service is running; stop and disable it before installing this unit.'
fi
if ! getent passwd dalitoolkit >/dev/null; then
    getent group dalitoolkit >/dev/null || groupadd --system dalitoolkit
    useradd --system --gid dalitoolkit --home-dir /var/lib/dali-toolkit \
        --no-create-home --shell /usr/sbin/nologin dalitoolkit
fi
[[ $(id -u dalitoolkit) != 0 && $(id -gn dalitoolkit) == dalitoolkit ]] || fail 'The dedicated dalitoolkit user/group is required.'
state=/var/lib/dali-toolkit
config=/etc/dali-toolkit
target=$state/bin/dali-toolkit-server
entry=/usr/local/bin/dali-toolkit-server
unit=/etc/systemd/system/dali-toolkit-server.service
for directory in "$state" "$state/bin" "$state/firmware" "$config"; do
    [[ ! -L "$directory" ]] || fail "Refusing deployment directory symlink: $directory"
done
install -d -o root -g dalitoolkit -m 0750 "$config"
install -d -o dalitoolkit -g dalitoolkit -m 0750 "$state"
runuser -u dalitoolkit -- mkdir -p -- "$state/bin" "$state/firmware"
runuser -u dalitoolkit -- chmod 0750 "$state/bin" "$state/firmware"
# Use the executable filesystem, with a root-owned parent the daemon cannot rename.
stage=$(mktemp -d /var/lib/.dali-toolkit-install.XXXXXXXX)
chown root:dalitoolkit "$stage"
chmod 0750 "$stage"
hba_backup=
hba_file=
stopped=false
cleanup() {
    result=$?
    trap - EXIT
    if [[ -n "$hba_backup" ]]; then
        cp -p -- "$hba_backup" "$hba_file"
        pg 'SELECT pg_reload_conf();' >/dev/null || true
    fi
    if $stopped && ((result != 0)); then
        printf 'Installation failed after stopping the service. Inspect configuration, then restart dali-toolkit-server.\n' >&2
    fi
    if [[ "$stage" == /var/lib/.dali-toolkit-install.* ]]; then rm -rf -- "$stage"; fi
    exit "$result"
}
trap cleanup EXIT
downloaded_channel=
if [[ -z "$binary" ]]; then
    if [[ -f "$target" && ! -L "$target" ]]; then
        binary=$target
    else
        download_args=(--output "$stage/download" --arch "$arch" --channel "$channel")
        if $use_mirror; then download_args+=(--use-mirror); fi
        downloaded_channel=$(python3 "$script_dir/install_download.py" "${download_args[@]}")
        binary=$stage/download
    fi
fi
[[ ! -L "$target" ]] || fail 'Managed binary must be a regular file.'
if [[ -f "$target" ]] && ! cmp -s -- "$binary" "$target"; then
    fail 'Managed binary already exists and differs. Upgrade through the signed server updater.'
fi
if [[ -L "$entry" ]]; then
    [[ $(realpath -- "$entry") == "$target" ]] || fail 'Existing entry-point symlink has another target.'
elif [[ -e "$entry" ]] && ! cmp -s -- "$entry" "$binary"; then
    fail 'Existing entry-point binary differs from --binary; preserve it and migrate manually.'
fi
if [[ "$binary" != "$target" && -e "$binary.update.json" ]]; then
    fail 'Source binary has an update journal; migrate its complete updater state manually.'
fi
install -o root -g dalitoolkit -m 0755 "$binary" "$stage/server"
cd /
version=$(runuser -u dalitoolkit -- "$stage/server" --version)
[[ -n "$version" && "$version" != *$'\n'* ]] || fail 'Executable returned an invalid version.'
license_ready=false
if [[ -n "$license_source" ]]; then
    install -o root -g dalitoolkit -m 0640 "$license_source" "$stage/license.json"
    runuser -u dalitoolkit -- env SERVER_LICENSE_FILE="$stage/license.json" \
        "$stage/server" --license-status >/dev/null || fail 'Provided licence is invalid for this machine.'
    license_ready=true
elif [[ -f "$config/server-license.json" ]]; then
    runuser -u dalitoolkit -- env SERVER_LICENSE_FILE="$config/server-license.json" \
        "$stage/server" --license-status >/dev/null || fail 'Existing licence is invalid; provide --license PATH.'
    license_ready=true
fi
if ! $license_ready && systemctl is-active --quiet dali-toolkit-server; then
    fail 'Running service has no licence in the managed location; migrate its licence first.'
fi

printf 'Configuring local PostgreSQL...\n'
systemctl enable --now postgresql
pg() { runuser -u postgres -- psql -X -w -h "$pg_socket" -p "$pg_port" -d postgres -v ON_ERROR_STOP=1 -Atqc "$1"; }
ready=false
for ((attempt=0; attempt<30; attempt++)); do
    if pg 'SELECT 1;' >/dev/null 2>&1; then ready=true; break; fi
    sleep 1
done
$ready || fail 'PostgreSQL socket is unavailable; check the cluster and --pg-socket/--pg-port.'
if [[ $(pg "SELECT count(*) FROM pg_roles WHERE rolname='dalitoolkit';") == 0 ]]; then
    runuser -u postgres -- createuser -w -h "$pg_socket" -p "$pg_port" \
        --no-superuser --no-createdb --no-createrole dalitoolkit
fi
[[ $(pg "SELECT rolcanlogin AND NOT (rolsuper OR rolcreatedb OR rolcreaterole OR rolreplication OR rolbypassrls) FROM pg_roles WHERE rolname='dalitoolkit';") == t ]] || fail 'Existing database role is not a restricted login role; review it manually.'
if [[ $(pg "SELECT count(*) FROM pg_database WHERE datname='dali_toolkit';") == 0 ]]; then
    runuser -u postgres -- createdb -w -h "$pg_socket" -p "$pg_port" --owner=dalitoolkit dali_toolkit
fi
[[ $(pg "SELECT pg_get_userbyid(datdba) FROM pg_database WHERE datname='dali_toolkit';") == dalitoolkit ]] || fail 'Existing database has another owner; refusing to change ownership.'
[[ $(pg 'SELECT count(*) FROM pg_hba_file_rules WHERE error IS NOT NULL;') == 0 ]] || fail 'Existing pg_hba.conf has errors; fix them first.'
hba_file=$(pg 'SHOW hba_file;')
hba_backup=$(python3 "$script_dir/install_config.py" hba --output "$hba_file")
[[ $(pg 'SELECT count(*) FROM pg_hba_file_rules WHERE error IS NOT NULL;') == 0 ]] || fail 'HBA validation failed; restoring backup.'
[[ $(pg 'SELECT pg_reload_conf();') == t ]] || fail 'PostgreSQL reload failed; restoring HBA backup.'
ready=false
for ((attempt=0; attempt<10; attempt++)); do
    if [[ $(runuser -u dalitoolkit -- psql -X -w -h "$pg_socket" -p "$pg_port" \
        -d dali_toolkit -Atqc "SELECT current_user='dalitoolkit' AND inet_client_addr() IS NULL;" 2>/dev/null) == t ]]; then
        ready=true; break
    fi
    sleep 1
done
$ready || fail 'PostgreSQL peer authentication failed; restoring HBA backup.'
hba_backup=  # The validated backup remains on disk; no automatic restore now.

python3 "$script_dir/install_config.py" environment --template "$script_dir/server.env.example" \
    --output "$config/server.env" --gid "$(id -g dalitoolkit)" --socket "$pg_socket" \
    --port "$pg_port" --public-url "$public_url" --node-key "$node_key"
if [[ ! -e "$state/server-update.json" ]]; then
    python3 - "$script_dir/server-update.json" "$stage/server-update.json" "$downloaded_channel" "$channel" "$use_mirror" <<'PY'
import json
from pathlib import Path
import sys
template, output, downloaded, channel, mirror = sys.argv[1:]
settings = json.loads(Path(template).read_text())
settings['channel'] = downloaded or ('dev' if channel == 'dev' else 'stable')
settings['use_mirror'] = mirror == 'true'
Path(output).write_text(json.dumps(settings, indent=2) + '\n')
PY
    chown root:dalitoolkit "$stage/server-update.json"
    chmod 0640 "$stage/server-update.json"
    runuser -u dalitoolkit -- install -m 0600 "$stage/server-update.json" "$state/server-update.json"
fi
if systemctl is-active --quiet dali-toolkit-server; then
    systemctl stop dali-toolkit-server
    stopped=true
fi
if [[ ! -e "$target" ]]; then
    runuser -u dalitoolkit -- install -m 0755 "$stage/server" "$target"
    printf '%s\n' "$version" | runuser -u dalitoolkit -- tee "$state/bin/VERSION" >/dev/null
fi
if [[ ! -L "$entry" ]]; then
    if [[ -e "$entry" ]]; then mv -- "$entry" "$entry.pre-systemd-$(date +%s%N)"; fi
    ln -s -- "$target" "$entry"
fi
if [[ -n "$license_source" ]]; then
    if [[ -f "$config/server-license.json" ]]; then
        cp -p -- "$config/server-license.json" "$config/server-license.json.before-install-$(date +%s%N)"
    fi
    install -o root -g dalitoolkit -m 0640 "$stage/license.json" "$config/server-license.json"
fi
if [[ -f "$unit" ]] && ! cmp -s "$unit" "$script_dir/dali-toolkit-server.service"; then
    cp -p -- "$unit" "$unit.before-install-$(date +%s%N)"
fi
install -o root -g root -m 0644 "$script_dir/dali-toolkit-server.service" "$unit"
systemd-analyze verify "$unit"
systemctl daemon-reload
if ! $license_ready; then
    printf '\nSetup complete; machine licence required. The service has not been started.\nMachine hash: '
    runuser -u dalitoolkit -- "$target" --license-request
    printf 'Issue a licence on your development machine, then rerun:\n  curl -fsSL https://raw.githubusercontent.com/tonylu00/DALI-Toolkit-server-build/main/install.sh | sudo bash -s -- --license /path/to/server-license.json\n'
    exit 2
fi
systemctl enable --now dali-toolkit-server
stopped=false
healthy=false
for ((attempt=0; attempt<120; attempt++)); do
    if systemctl is-active --quiet dali-toolkit-server && \
        curl --silent --fail --max-time 2 http://127.0.0.1:8189/health >/dev/null; then
        healthy=true; break
    fi
    sleep 1
done
$healthy || fail 'Service did not become healthy. Inspect: journalctl -u dali-toolkit-server -n 100'
printf '\nInstalled %s; HTTP health check passed at 127.0.0.1:8189.\n' "$version"
printf 'Configuration: /etc/dali-toolkit/server.env\nUpdate settings: /var/lib/dali-toolkit/server-update.json\n'
printf 'Read AUTH_BOOTSTRAP_TOKEN privately from server.env for the first DaliMaster login.\n'
printf 'HAProxy, certificates, DNS and firewall have not been changed.\n'
DALI_INSTALL_PAYLOAD_0_END
    cat > "$bundle/install_dependencies.sh" <<'DALI_INSTALL_PAYLOAD_1_END'
#!/usr/bin/env bash
# Sourced by install_body.sh; keep dependency discovery independent of provisioning.

dali_command_works() {
    command -v "$1" >/dev/null 2>&1 && "$1" --version >/dev/null 2>&1
}

dali_postgres_binaries() {
    local binary
    for binary in /usr/lib/postgresql/*/bin/postgres /usr/local/pgsql/bin/postgres; do
        [[ ! -x "$binary" ]] || printf '%s\n' "$binary"
    done
}

dali_install_dependencies() {
    local skip_packages=$1 pg_socket=$2 pg_port=$3
    local inventory package status binary version clusters command candidate
    local server_present=false clients_present=true server_version=
    local -a missing=() versions=()
    local -A installed=()

    $skip_packages && return 0
    inventory=$(dpkg-query -W -f='${binary:Package}\t${Status}\n') || {
        printf 'ERROR: Cannot read installed packages; refusing to guess dependencies.\n' >&2
        return 1
    }
    while IFS=$'\t' read -r package status; do
        package=${package%%:*}
        # The selection can be "hold" as well as "install".
        [[ "$status" == *' ok installed' ]] || continue
        installed["$package"]=1
        if [[ "$package" =~ ^postgresql-([0-9]+(\.[0-9]+)?)$ ]]; then
            server_present=true
            versions+=("${BASH_REMATCH[1]}")
        elif [[ "$package" == postgresql ]]; then
            server_present=true
        fi
    done <<< "$inventory"

    # A working server need not have an unversioned Debian meta-package or be on PATH.
    if command -v postgres >/dev/null 2>&1; then
        server_present=true
        version=$(postgres --version 2>/dev/null || true)
        if [[ "$version" =~ PostgreSQL\)\ ([0-9]+)(\.([0-9]+))? ]]; then
            candidate=${BASH_REMATCH[1]}
            if ((candidate < 10)) && [[ -n ${BASH_REMATCH[3]:-} ]]; then
                candidate+=.${BASH_REMATCH[3]}
            fi
            versions+=("$candidate")
        fi
    fi
    while IFS= read -r binary; do
        [[ -n "$binary" ]] || continue
        server_present=true
        if [[ "$binary" =~ /postgresql/([0-9]+(\.[0-9]+)?)/bin/postgres$ ]]; then
            versions+=("${BASH_REMATCH[1]}")
        fi
    done < <(dali_postgres_binaries)
    if command -v pg_lsclusters >/dev/null 2>&1; then
        clusters=$(pg_lsclusters --no-header) || {
            printf 'ERROR: Cannot inspect PostgreSQL clusters; refusing to install another server.\n' >&2
            return 1
        }
        while read -r version candidate; do
            [[ "$version" =~ ^[0-9]+(\.[0-9]+)?$ ]] || continue
            server_present=true
            versions+=("$version")
        done <<< "$clusters"
    fi
    [[ ! -S "$pg_socket/.s.PGSQL.$pg_port" ]] || server_present=true
    if ((${#versions[@]})); then
        server_version=$(printf '%s\n' "${versions[@]}" | sort -V | tail -n 1)
    fi

    # pg_wrapper may exist even when no actual PostgreSQL client is installed.
    for command in psql createuser createdb; do
        dali_command_works "$command" || clients_present=false
    done
    if $server_present; then
        printf 'Reusing existing PostgreSQL; no server package will be installed.\n'
    else
        missing+=(postgresql)
    fi
    if ! $clients_present; then
        candidate=postgresql-client
        [[ -z "$server_version" ]] || candidate="postgresql-client-$server_version"
        missing+=("$candidate")
    fi
    for command in curl python3 openssl; do
        dali_command_works "$command" || missing+=("$command")
    done
    if [[ ! -s /etc/ssl/certs/ca-certificates.crt && -z ${installed[ca-certificates]:-} ]]; then
        missing+=(ca-certificates)
    fi

    # An installed but unusable package needs repair, not an implicit upgrade/reinstall.
    for package in "${missing[@]}"; do
        if [[ -n ${installed[$package]:-} ]]; then
            printf 'ERROR: %s is installed but its required commands do not work; repair it and rerun.\n' "$package" >&2
            return 1
        fi
    done
    if ((${#missing[@]})); then
        printf 'Installing missing components: %s\n' "${missing[*]}"
        apt-get update || return
        DEBIAN_FRONTEND=noninteractive apt-get install -y --no-upgrade "${missing[@]}" || return
    else
        printf 'All required components are present; skipping apt.\n'
    fi
}
DALI_INSTALL_PAYLOAD_1_END
    cat > "$bundle/install_config.py" <<'DALI_INSTALL_PAYLOAD_2_END'
#!/usr/bin/env python3
"""Installer file operations; standard library only, never prints secret values."""
import argparse
import base64
import os
from pathlib import Path
import re
import secrets
import shlex
import shutil
import socket as socket_api
import stat
import tempfile
import time
from urllib.parse import urlsplit

DEFAULT_URL = "https://dali.tonycloud.cn:28443"
KEY_NAMES = ("device-secret-wrap.key", "mqtt-token-signing.key", "project-vault.key")
HBA_BEGIN = "# BEGIN DALI-Toolkit installer"
HBA_END = "# END DALI-Toolkit installer"


def public_endpoint(value):
    url = urlsplit(value)
    host = url.hostname or ""
    labels = host.split(".")
    if (url.scheme != "https" or url.username is not None or url.password is not None
            or url.path not in ("", "/") or url.query or url.fragment
            or len(labels) < 2 or len(host) > 253
            or all(label.isdigit() for label in labels)
            or any(not re.fullmatch(r"[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?", label)
                   for label in labels)):
        raise ValueError("Public URL must be https://DNS-NAME[:PORT] without a path or credentials")
    port = url.port  # Also validates malformed/out-of-range ports.
    if port is not None and port < 1:
        raise ValueError("Public port must be between 1 and 65535")
    authority = host + (f":{port}" if port is not None and port != 443 else "")
    return f"https://{authority}", host, f"wss://{authority}"


def env_values(text):
    values = {}
    for line in text.splitlines():
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        key, separator, raw = line.partition("=")
        if not separator or not re.fullmatch(r"[A-Z][A-Z0-9_]*", key):
            raise ValueError("Existing environment file must use one KEY=value per line")
        if key in values:
            raise ValueError(f"Duplicate environment setting: {key}")
        parsed = shlex.split(raw, comments=False)
        if len(parsed) > 1:
            raise ValueError(f"Quote values containing spaces: {key}")
        values[key] = parsed[0] if parsed else ""
    return values


def replace_values(text, values):
    lines = []
    remaining = dict(values)
    for line in text.splitlines():
        key = line.partition("=")[0]
        if key in remaining:
            # Every replacement is generated or validated; shell syntax is not used.
            value = remaining.pop(key).replace("\\", "\\\\").replace('"', '\\"')
            line = f'{key}="{value}"'
        lines.append(line)
    lines.extend(f'{key}="{value}"' for key, value in remaining.items())
    return "\n".join(lines) + "\n"


def atomic_write(path, data, mode, uid=None, gid=None):
    if path.is_symlink():
        raise ValueError(f"Refusing to replace symlink: {path}")
    fd, temporary = tempfile.mkstemp(prefix=".dali-install-", dir=path.parent)
    try:
        with os.fdopen(fd, "wb") as stream:
            if uid is not None and os.name == "posix":
                os.fchown(stream.fileno(), uid, gid)
            os.chmod(temporary, mode)
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)


def backup(path):
    target = path.with_name(path.name + f".before-install-{time.time_ns()}")
    shutil.copy2(path, target)
    if os.name == "posix":
        info = path.stat()
        os.chown(target, info.st_uid, info.st_gid)
    return target


def prepare_environment(template, destination, socket, port, public_url, node_key, gid):
    if destination.is_symlink():
        raise ValueError("Refusing environment file symlink")
    existing = destination.exists()
    text = (destination if existing else template).read_text(encoding="utf-8")
    old = env_values(text)
    expected_paths = {
        "SERVER_LICENSE_FILE": "/etc/dali-toolkit/server-license.json",
        "SERVER_UPDATE_CONFIG_FILE": "/var/lib/dali-toolkit/server-update.json",
        "DEVICE_SECRET_WRAP_KEY_FILE": "/etc/dali-toolkit/device-secret-wrap.key",
        "MQTT_TOKEN_SIGNING_KEY_FILE": "/etc/dali-toolkit/mqtt-token-signing.key",
        "PROJECT_VAULT_WRAP_KEY_FILE": "/etc/dali-toolkit/project-vault.key",
    }
    if existing:
        for key, path in expected_paths.items():
            if old.get(key) != path:
                raise ValueError(f"Existing {key} uses a different layout; migrate it manually")
        if not old.get("AUTH_JWT_SECRET") or old["AUTH_JWT_SECRET"].startswith("REPLACE_"):
            raise ValueError("Existing AUTH_JWT_SECRET is missing; configure it before rerunning")
    changes = dict(expected_paths)
    changes.update(SERVER_ADDR="127.0.0.1:8189", PG_DSN=(
        f"host={socket} port={port} user=dalitoolkit dbname=dali_toolkit "
        "sslmode=disable connect_timeout=5"))
    if not existing:
        changes.update(AUTH_JWT_SECRET=secrets.token_hex(32), AUTH_BOOTSTRAP_TOKEN=secrets.token_hex(32))
    if public_url or not existing:
        url, host, ws = public_endpoint(public_url or DEFAULT_URL)
        changes.update(CLOUD_PUBLIC_BASE_URL=url, CLOUD_MQTT_URL=ws + "/mqtt",
                       CLOUD_WS_URL=ws + "/ws", DEVICE_CLOUD_API_BASE_URLS=url,
                       DEVICE_CLOUD_BROKER_URIS=host + "=" + ws + "/mqtt",
                       DEVICE_CLOUD_ALLOWED_HOSTS=host)
    if node_key or not existing:
        changes["CLOUD_NODE_KEY"] = node_key or socket_api.gethostname().split(".")[0]
        if not re.fullmatch(r"[A-Za-z0-9_-]{1,128}", changes["CLOUD_NODE_KEY"]):
            raise ValueError("Use --node-key with 1-128 letters, digits, underscores or hyphens")
    result = replace_values(text, changes).encode()
    # Validate ALL existing keys before creating anything. Missing keys on an
    # existing deployment must never silently replace its encryption identity.
    for name in KEY_NAMES:
        key = destination.parent / name
        if key.is_symlink():
            raise ValueError(f"Refusing runtime key symlink: {name}")
        if key.exists():
            material = key.read_bytes().strip()
            if len(base64.b64decode(material, validate=True)) != 32:
                raise ValueError(f"Invalid runtime key: {name}")
        elif existing:
            raise ValueError(f"Missing existing runtime key: {name}; restore its backup")
    for name in KEY_NAMES:
        key = destination.parent / name
        if not key.exists():
            atomic_write(key, base64.b64encode(secrets.token_bytes(32)) + b"\n", 0o640, 0, gid)
    if not existing or destination.read_bytes() != result:
        if existing:
            backup(destination)
        atomic_write(destination, result, 0o600, 0, 0)


def hba_text(text):
    if HBA_BEGIN in text or HBA_END in text:
        if text.count(HBA_BEGIN) != 1 or text.count(HBA_END) != 1:
            raise ValueError("Malformed DALI-Toolkit HBA markers; review pg_hba.conf")
        start = text.index(HBA_BEGIN)
        end = text.index(HBA_END) + len(HBA_END)
        if end <= start:
            raise ValueError("Malformed DALI-Toolkit HBA marker order")
        text = text[:start] + text[end:].removeprefix("\n")
    return f"{HBA_BEGIN}\nlocal dali_toolkit dalitoolkit peer\n{HBA_END}\n" + text


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("action", choices=("check", "environment", "hba"))
    parser.add_argument("--public-url", default="")
    parser.add_argument("--node-key", default="")
    parser.add_argument("--socket", default="/var/run/postgresql")
    parser.add_argument("--port", type=int, default=5432)
    parser.add_argument("--template", type=Path)
    parser.add_argument("--output", type=Path)
    parser.add_argument("--gid", type=int)
    args = parser.parse_args()
    public_endpoint(args.public_url or DEFAULT_URL)
    if not re.fullmatch(r"/[A-Za-z0-9_./-]+", args.socket) or not 1 <= args.port <= 65535:
        raise ValueError("Use an absolute socket directory without spaces and port 1-65535")
    if args.node_key and not re.fullmatch(r"[A-Za-z0-9_-]{1,128}", args.node_key):
        raise ValueError("Invalid node key")
    if args.action == "environment":
        prepare_environment(args.template, args.output, args.socket, args.port,
                            args.public_url, args.node_key, args.gid)
    elif args.action == "hba":
        path = args.output.resolve(strict=True)
        original = path.read_text(encoding="utf-8")
        replacement = hba_text(original)
        if replacement != original:
            saved = backup(path)
            info = path.stat()
            atomic_write(path, replacement.encode(), stat.S_IMODE(info.st_mode), info.st_uid, info.st_gid)
            print(saved)


if __name__ == "__main__":
    try:
        main()
    except (ValueError, OSError) as error:
        raise SystemExit(f"Configuration error: {error}")
