#!/usr/bin/env python3
"""Anonymous release download with the server's Ed25519 trust contract."""
import argparse
import base64
import hashlib
import json
from pathlib import Path
import re
import subprocess
import sys
import tempfile
import time
import urllib.error
import urllib.parse
import urllib.request

REPOSITORY = "tonylu00/DALI-Toolkit-server-build"
PUBLIC_KEY = "zGWiiF8JL4iWertPBL30lmn97WGs/Jy7w8ofiOFvm6E="
MAX_BINARY = 128 << 20
VERSION = re.compile(r"v(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)?")


def version_key(version):
    match = VERSION.fullmatch(version)
    if not match:
        raise ValueError("Invalid release version")
    major, minor, patch, pre = match.groups()
    identifiers = () if pre is None else tuple(
        (0, int(part)) if part.isdigit() else (1, part) for part in pre.split("."))
    if pre and any(part.isdigit() and len(part) > 1 and part.startswith("0") for part in pre.split(".")):
        raise ValueError("Invalid prerelease version")
    return int(major), int(minor), int(patch), pre is None, identifiers


def select_release(releases, channel, name):
    candidates = []
    for release in releases:
        if release.get("draft"):
            continue
        try:
            key = version_key(release.get("tag_name", ""))
        except (ValueError, TypeError):
            continue
        stable = key[3] and not release.get("prerelease")
        names = [a.get("name") for a in release.get("assets", []) if a.get("state") == "uploaded"]
        if any(names.count(asset) != 1 for asset in (name, name + ".manifest.json", name + ".sig")):
            continue
        if channel != "stable" or stable:
            candidates.append((key, stable, release))
    if channel == "auto" and any(item[1] for item in candidates):
        candidates = [item for item in candidates if item[1]]
    if not candidates:
        raise ValueError(f"No complete {channel} release is available for {name}")
    return max(candidates, key=lambda item: item[0])[2]


def allowed_url(url):
    parsed = urllib.parse.urlsplit(url)
    host = parsed.hostname or ""
    return (parsed.scheme == "https" and parsed.username is None and parsed.password is None
            and (host in ("github.com", "api.github.com", "mirrors.tonycloud.cn")
                 or host.endswith(".githubusercontent.com")))


class HTTPSRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, request, fp, code, message, headers, new_url):
        if not allowed_url(new_url):
            raise ValueError("Release redirect refused")
        return super().redirect_request(request, fp, code, message, headers, new_url)


def download(url, destination, limit, use_mirror=False):
    if not allowed_url(url):
        raise ValueError("Release URL refused")
    mirror = "https://mirrors.tonycloud.cn/" + url.removeprefix("https://")
    targets = [mirror, url] if use_mirror else [url, mirror]
    opener = urllib.request.build_opener(HTTPSRedirect())
    for target in targets:
        try:
            request = urllib.request.Request(target, headers={"User-Agent": "DALI-Toolkit-installer"})
            deadline = time.monotonic() + 300
            with opener.open(request, timeout=30) as response, destination.open("wb") as output:
                size = 0
                while True:
                    data = response.read(min(65536, limit + 1 - size))
                    if not data:
                        return
                    size += len(data)
                    if size > limit or time.monotonic() > deadline:
                        raise ValueError("Release download exceeds its size or time limit")
                    output.write(data)
        except (OSError, urllib.error.URLError, ValueError):
            destination.unlink(missing_ok=True)
    raise ValueError("Download failed through GitHub and mirror")


def verify_manifest(payload, signature, name, version, channel, public_key=PUBLIC_KEY):
    # Signatures cover exact bytes, including the domain-separation prefix.
    raw_signature = base64.b64decode(signature.strip(), validate=True)
    key = base64.b64decode(public_key, validate=True)
    if len(raw_signature) != 64 or len(key) != 32 or len(payload) > 16384:
        raise ValueError("Invalid manifest signature")
    with tempfile.TemporaryDirectory(prefix="dali-verify-") as temporary:
        directory = Path(temporary)
        (directory / "key.der").write_bytes(bytes.fromhex("302a300506032b6570032100") + key)
        (directory / "signature").write_bytes(raw_signature)
        (directory / "payload").write_bytes(b"dali-server/update/v1\n" + payload)
        result = subprocess.run([
            "openssl", "pkeyutl", "-verify", "-pubin", "-keyform", "DER", "-rawin",
            "-inkey", str(directory / "key.der"), "-sigfile", str(directory / "signature"),
            "-in", str(directory / "payload")], capture_output=True, timeout=15)
        if result.returncode:
            raise ValueError("Release manifest signature is invalid")
    manifest = json.loads(payload)
    stable = version_key(version)[3]
    if (manifest.get("asset") != name or manifest.get("version") != version
            or manifest.get("channel") != ("stable" if stable else "dev")
            or (channel == "stable" and not stable)
            or type(manifest.get("size")) is not int or not 0 < manifest["size"] <= MAX_BINARY
            or not isinstance(manifest.get("sha256"), str)
            or not re.fullmatch(r"[0-9a-fA-F]{64}", manifest["sha256"])):
        raise ValueError("Release manifest does not match the selected version/platform")
    return manifest


def check_binary(binary, manifest):
    digest = hashlib.sha256()
    size = 0
    with binary.open("rb") as stream:
        for block in iter(lambda: stream.read(65536), b""):
            size += len(block)
            digest.update(block)
    if size != manifest["size"] or digest.hexdigest() != manifest["sha256"].lower():
        raise ValueError("Downloaded binary size or SHA-256 does not match its signed manifest")


def install_download(output, arch, channel, use_mirror):
    name = "dali-toolkit-server-linux-" + arch
    with tempfile.TemporaryDirectory(prefix="dali-release-", dir=output.parent) as temporary:
        directory = Path(temporary)
        download(f"https://api.github.com/repos/{REPOSITORY}/releases?per_page=100",
                 directory / "releases.json", 2 << 20, use_mirror)
        release = select_release(json.loads((directory / "releases.json").read_bytes()), channel, name)
        version = release["tag_name"]
        base = f"https://github.com/{REPOSITORY}/releases/download/{urllib.parse.quote(version, safe='')}/{name}"
        download(base + ".manifest.json", directory / "manifest", 16384, use_mirror)
        download(base + ".sig", directory / "signature", 256, use_mirror)
        manifest = verify_manifest((directory / "manifest").read_bytes(),
                                   (directory / "signature").read_bytes(), name, version, channel)
        if channel == "auto" and manifest["channel"] == "dev":
            print("No stable release is published; installing the latest signed public dev build.", file=sys.stderr)
        print(f"Downloading {version} for Linux {arch}...", file=sys.stderr)
        download(base, directory / "binary", manifest["size"], use_mirror)
        check_binary(directory / "binary", manifest)
        # No execute permission until both signature and hash checks have passed.
        (directory / "binary").replace(output)
        return manifest["channel"]


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", required=True, type=Path)
    parser.add_argument("--arch", required=True, choices=("x64", "aarch64"))
    parser.add_argument("--channel", choices=("auto", "stable", "dev"), default="auto")
    parser.add_argument("--use-mirror", action="store_true")
    args = parser.parse_args()
    try:
        print(install_download(args.output, args.arch, args.channel, args.use_mirror))
    except (ValueError, OSError, subprocess.SubprocessError) as error:
        raise SystemExit(f"Release download failed: {error}")
DALI_INSTALL_PAYLOAD_3_END
